<?php require 'config.php';require_role('petugas');$page_title='Pembayaran';$msg='';
if(isset($_POST['simpan'])){$tid=(int)$_POST['tagihan_id'];$tg=$conn->query("SELECT * FROM tagihan WHERE id=$tid")->fetch_assoc();if($tg){$no='KW-'.date('YmdHis').'-'.random_int(100,999);$s=$conn->prepare("INSERT INTO pembayaran(tagihan_id,petugas_id,tanggal_bayar,nominal,metode,status,nomor_kwitansi,keterangan) VALUES(?,?,?,?,?,'terverifikasi',?,?)");$s->bind_param('iisdsss',$tid,$_SESSION['user']['id'],$_POST['tanggal'],$tg['nominal'],$_POST['metode'],$no,$_POST['keterangan']);$s->execute();$conn->query("UPDATE tagihan SET status='lunas' WHERE id=$tid");log_action('PEMBAYARAN','pembayaran',$s->insert_id,$no);$msg=$no;}}
$sel=(int)($_GET['tagihan']??0);$res=$conn->query("SELECT tg.*,w.nomor_pelanggan,w.nama FROM tagihan tg JOIN warga w ON w.id=tg.warga_id WHERE tg.status<>'lunas' ORDER BY w.nama");
include 'partials/header.php';?>
<div class="page-title"><div><h2>Input Pembayaran</h2><p class="muted">Catat pembayaran dan cetak kwitansi.</p></div></div>
<?php if($msg):?><div class="alert success">Pembayaran tersimpan. Nomor kwitansi: <b><?=e($msg)?></b> — <a href="kwitansi.php?no=<?=urlencode($msg)?>">Cetak kwitansi</a></div><?php endif;?>
<div class="card"><form method="post" class="formgrid"><label>Tagihan<select name="tagihan_id" required><?php while($r=$res->fetch_assoc()):?><option value="<?=$r['id']?>" <?=$sel===$r['id']?'selected':''?>><?=e($r['nomor_pelanggan'].' - '.$r['nama'].' | '.periode_label($r['bulan'],$r['tahun']).' | '.rupiah($r['nominal']))?></option><?php endwhile;?></select></label><label>Tanggal<input type="date" name="tanggal" value="<?=date('Y-m-d')?>" required></label><label>Metode<select name="metode"><option>tunai</option><option>transfer</option><option>qris</option></select></label><input name="keterangan" placeholder="Keterangan (opsional)"><button name="simpan" class="btn primary">Simpan Pembayaran</button></form></div><?php include 'partials/footer.php';?>